// Stati: dichiarato (dal proprietario) · documentato (fonte citata) · ipotesi · misurato · da_verificare.
// Un valore `null` significa SCONOSCIUTO: non sostituirlo con zero.
export const SCHEMA = 3; // 3 = documenti (manuali) ed estratti; // 2 = progetti, base fissa, stati d'uso, passi classificati, inventario collegato ai lavori, apparecchi

// Passi delle guide: ogni passo dichiara la sua natura. Prefisso nel testo: [D] documentata da fonte · [P] proposta progettuale · [V] verifica ancora necessaria.
const TAG = { D: 'documentata', P: 'proposta', V: 'verifica' };
export const passo = (x) => { if (typeof x !== 'string') return x; const m = x.match(/^\[([DPV])\]\s*([\s\S]*)$/); return m ? { t: m[2], tipo: TAG[m[1]] } : { t: x, tipo: 'verifica' }; };
const L = (o) => ({ stato: 'da_pianificare', priorita: 2, chi: 'io', zona: '', problemi: [], obiettivo: '', iniziali: '', verifiche: [], materiali: [], attrezzi: [],
  tipoPassi: 'verifica', competenze: '', dipende: [], ore: null, fermo_g: null, attese: '', fonti: [], esito: { data: null, nota: '', foto: [] },
  materialiInv: [], attrezziInv: [], sessioni: [], schemi: [], ...o,
  passi: (o.passi || []).map(passo), accettazione: (o.accettazione || []).map((t) => ({ t, ok: false })) });

